//============================================================================//
// @brief  Print a string for CAN function with consideration to RTOS
//         implementation and debug mode. Also record the logs into the CAN debug
//         file. Shouldn't be used to print received CAN messages.
// @param  format: formatted string for print.
//         ... varied length argument
// @retval None.
//============================================================================//
void CANprintf2(char *format, ...)
{
    va_list arg;
    osStatus osRes;
#if ENABLE_DEBUG_CAN_REC
    char cDebugLog[128] = {0};
    uint8_t u8BCD[7] = {0};
    time_t ttTime;
    char *pcPtr;
#endif

#if ENABLE_DEBUG_CAN_REC
    if (Datalog_IsRecordMode(REC_CAN_DBG))
    {
        ttTime = System_GetTime();

        SecToBCDTime(ttTime, u8BCD);

        va_start(arg, format);

        vsprintf(cDebugLog, format, arg);

        va_end(arg);

        pcPtr = cDebugLog + strlen(cDebugLog);

        sprintf(pcPtr, " (%02X%02X/%02X/%02X %02X:%02X:%02X)",
                u8BCD[0],
                u8BCD[1],
                u8BCD[2],
                u8BCD[3],
                u8BCD[4],
                u8BCD[5],
                u8BCD[6]);

        SD_AddBuffToFile((char *)FILENAME_CAN_DEBUG_MSG_FILE, (uint8_t *)cDebugLog, strlen(cDebugLog));
    }
#endif

    if ((UART_IsDebugMode(DBG_EXT) == FALSE) || (sdRequest.sdCmd == SD_MKFS))
        return;

    va_start(arg, format);

    if (bPrintfEn)
    {
        if (bRTOS_En)
        {
            // Acquire uart synchronization
            if (UART_IsTerminalUsingSET())
                osRes = osMutexWait(mutex_uart_user[SET_COMPORT_DEF], S_2_mS(5));
            else
                osRes = osMutexWait(mutex_uart_user[DB9_COMPORT_DEF], S_2_mS(5));

            if (osRes != osOK)
            {
                va_end(arg);

                return;
            }
        }

        vfprintf(stdout, format, arg);

        if (bRTOS_En)
        {
            // Release uart synchronization
            if (UART_IsTerminalUsingSET())
                osMutexRelease(mutex_uart_user[SET_COMPORT_DEF]);
            else
                osMutexRelease(mutex_uart_user[DB9_COMPORT_DEF]);
        }
    }

    va_end(arg);
}

